SELECT * FROM (SELECT g.*, RANK() OVER (ORDER BY PageViews DESC) AS rnk FROM (SELECT WindowClientWidth, WindowClientHeight, COUNT(*) AS PageViews FROM hits WHERE CounterID = 62 AND EventDate >= '2013-07-01' AND EventDate <= '2013-07-31' AND IsRefresh = 0 AND DontCountHits = 0 AND URLHash = 2868770270353813622 GROUP BY WindowClientWidth, WindowClientHeight) g) ranked WHERE rnk <= 10 ORDER BY rnk;
